AtomicLong lastSeen = new AtomicLong(System.nanoTime());   // arrivals: lastSeen.set(System.nanoTime());
ScheduledExecutorService monitor = Executors.newSingleThreadScheduledExecutor(r -> {
    Thread t = new Thread(r, "flow-watchman"); t.setDaemon(true); return t; });
monitor.scheduleWithFixedDelay(() -> {
    try {
        Duration silent = Duration.ofNanos(System.nanoTime() - lastSeen.get());
        if (silent.compareTo(grace) > 0) publish(subject, silent);   // metric/alert sink + state machine
    } catch (Throwable t) { log.error("watchman tick failed", t); }   // never let the task die
}, 0, 5, TimeUnit.SECONDS);

